// The translucent menu bar of 10.6 with a graphics card: not CoreUI's art, but generated by the window
// server from what is behind it (CGXSetMenuBarFilter's standard filter, CIMenuGenerator, in QuartzCore).
// What it does, in the gamma-encoded RGB it works in:
//
//   B  the desktop behind the bar, Gaussian-blurred (radius 1.6)
//   L  the mean of the desktop's R, G and B over the bar (not blurred)
//   w  = mix(0.60, 0.25, L)     a white veil, stronger over dark desktops    (inputBarWhiteParams)
//   k  = mix(0.35, 0.15, L)     a lift, stronger over dark desktops          (inputBarRampParams .x .y)
//   y  from the top, h the bar's height:
//   C  = (B (1 - w) + w) / (1 - k (1 - y/h)^0.75)                            (ramp .w = 0.75)
//   the top 1.5 px: C toward white by 0.5                                    (inputBarTopLine)
//   the bottom 1.5 px: B at 0.59, the bar's edge in the desktop's own hue
//
// Checked against a 10.6 screenshot: within 5 levels on average (docs/reverse-status.md).
#pragma once

#include <QImage>

// `behind`: the desktop under the bar, the bar's size.
QImage generateMenuBar(const QImage &behind);

// The Apple over that bar (CIMenuAppleGenerator): drawn into `bar` at x 17, from the 32 x 22 picture
// extract.py takes out of QuartzCore. What it does, in the same RGB:
//
//   B  the desktop, blurred (radius 8); L its mean from x 17 to the bar's end
//   fill = B * mix(0.30, 0.075, L)                               a dark glass   (inputAppleBlackParams)
//   t = y / h from the top; fill /= 1 - mix(0.75, 0.5, L) * mix(0.5, 1, t^0.75)  lighter downwards (RampParams)
//   the shine: past a rounded corner of radius 8 around (7.5, 4) (ShineGeometry),
//              fill += clamp(v - 8, 0, 1) * t^2.75 * mix(0.6, 0.85, L)   (ShineParams)
//   an inner shadow: black, alpha 1 - the Apple's alpha blurred by 1.5  (ShadowParams)
//   kept inside the Apple; under it, the Apple in white at 0.6 one pixel lower (inputAppleBevel)
//
// Returns false (and leaves `bar` as it is) without the picture.
bool drawMenuApple(QImage &bar, const QImage &behind);
